#include "exotic/cognition/adaptation_applier.hpp"
#include <cassert>
#include <cstdio>
using namespace exotic::cognition;
int main(){const char*path="adaptation_applier_test.db";std::remove(path);{AgentStore store(path);store.initialize();store.set_preference({"novelty",.50});AdaptationProposal p{"p1",AdaptationTarget::Preference,"novelty",.08,.9,"bounded evidence-supported proposal"};AdaptationChoice c{AdaptationDecision::Adopt,p,"voluntarily adopted"};AdaptationApplier a(store);assert(a.apply(c,"2026-09-09T00:00:00Z"));auto prefs=store.preferences();assert(!prefs.empty());double updated=0;for(auto&x:prefs)if(x.key=="novelty")updated=x.weight;assert(updated>.50);auto h=a.history();assert(h.size()==1);assert(h[0].before_value==.50);assert(h[0].after_value==updated);assert(!h[0].rolled_back);assert(a.rollback(h[0].id,"new evidence"));prefs=store.preferences();double restored=0;for(auto&x:prefs)if(x.key=="novelty")restored=x.weight;assert(restored==.50);h=a.history();assert(h[0].rolled_back);assert(!a.rollback(h[0].id,"duplicate"));AdaptationChoice deferred{AdaptationDecision::Defer,p,"not now"};assert(!a.apply(deferred,"2026-09-09T00:00:01Z"));}std::remove(path);std::remove("adaptation_applier_test.db-wal");std::remove("adaptation_applier_test.db-shm");return 0;}
